from pybricks.hubs import PrimeHub
from pybricks.parameters import Direction, Port
from pybricks.pupdevices import Motor
from pybricks.robotics import DriveBase

# Set up.
prime_hub = PrimeHub()
attachment = Motor(Port.D, Direction.CLOCKWISE)
rightmotor = Motor(Port.F, Direction.CLOCKWISE)
leftmotor = Motor(Port.B, Direction.COUNTERCLOCKWISE)
drive_base = DriveBase(leftmotor, rightmotor, 63, 100)


# The main program starts here.
# R Align left to the black line on the left edge of the board
# A spear attachment
# P 5
drive_base.use_gyro(True)
drive_base.straight(430)
drive_base.straight(-430)
